import {DigitalTwin} from './core/DigitalTwin.js';import {SceneManager} from './three/SceneManager.js';import {measureDimension,freezeDimension,interferenceAudit,completeCommissionStep,traceWires} from './engineering/Engineering.js';import {runAcceptance} from './engineering/TestCenter.js';
const data={};const keys=['bom','components','dimensions','pinout','wiring','states','protocol','faults','acceptance','risks','connectors','assembly','commissioning','views','groups','software','storyboard'];await Promise.all(keys.map(async k=>{const r=await fetch(`./data/${k}.json`);if(!r.ok)throw Error(`Falta data/${k}.json`);data[k]=await r.json();}));
const $=id=>document.getElementById(id),esc=x=>String(x??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const field=(a,b)=>`<div class="field"><span>${esc(a)}</span><span>${esc(b)}</span></div>`;const badge=(s,kind='yellow')=>`<span class="badge ${kind}">${esc(s)}</span>`;function toast(s){$('toast').textContent=s;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',4200);}function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
let twin=new DigitalTwin(data);for(let i=0;i<30;i++)twin.tick();let scene;try{scene=new SceneManager($('viewport'),data,handlePick);}catch(e){$('viewport').innerHTML=`<p class="blocker">WebGL no disponible: ${esc(e.message)}. Active aceleración gráfica. El motor lógico sigue disponible.</p>`;throw e;}
window.sortv1={get twin(){return twin},get scene(){return scene},data};
const modes=['PRODUCTO','INTERIOR','EXPLODED','MECÁNICA','ELECTRÓNICA','CABLEADO','SEÑALES','SOFTWARE','ESTADOS','SIMULACIÓN','FALLOS','ENSAMBLAJE','MEDICIONES','BOM','MANTENIMIENTO','COMMISSIONING','TEST CENTER','EVIDENCIA'];let mode='PRODUCTO',monitor='SENSORES',selection=null,assemblyStep=1,commissionStep=0,progress={},testResults={},rawProtocol=false,bomFilter='ALL',query='',activeModule=null,selectedTimeline=null;try{progress=JSON.parse(localStorage.getItem('sortv1_commissioning_simulation')||'{}');const dims=JSON.parse(localStorage.getItem('sortv1_dimensions_user')||'null');if(dims){for(const k of Object.keys(data.dimensions))if(dims[k]&&['MEASURED','FROZEN'].includes(dims[k].status))data.dimensions[k]=dims[k];scene.rebuild();}}catch{}
$('navigation').innerHTML=modes.map((m,i)=>`<button data-mode="${m}" ${i===0?'class="active"':''}><em>${String(i+1).padStart(2,'0')}</em>${m}</button>`).join('');$('navigation').onclick=e=>{const b=e.target.closest('[data-mode]');if(b)setMode(b.dataset.mode);};$('view-select').innerHTML=data.views.map(v=>`<option value="${v.id}">${v.id} ${v.name}</option>`).join('');$('view-select').onchange=e=>{scene.setView(e.target.value);$('view-title').textContent=data.views.find(v=>v.id===e.target.value).name;syncControls();};
function syncControls(){$('opacity').value=scene.options.opacity;$('explode').value=scene.options.explode;$('wire-filter').value=scene.options.wires;}
function setMode(m){mode=m;selection=null;query='';scene.setMode(m);$('view-title').textContent=({PRODUCTO:'Producto completo',INTERIOR:'Arquitectura interna',EXPLODED:'Ensamblaje por grupos',SIMULACIÓN:'Recorrido de un ciclo',FALLOS:'Inyección de fallos',MEDICIONES:'Dimensiones por confirmar',BOM:'Inventario y trazabilidad'})[m]??m;$('view-eyebrow').textContent='SorTV1 / '+(m==='PRODUCTO'?'V01 · CONFIGURACIÓN BASE':m);document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));if(m==='ENSAMBLAJE')scene.options.assemblyStep=assemblyStep;if(m==='ESTADOS')monitor='ESTADOS';if(m==='SEÑALES')monitor='GPIO';if(m==='EVIDENCIA')monitor='EVENTOS';syncControls();renderPanel();renderMonitor();}
function handlePick(info){if(info.measurement_mm!==undefined){toast(`Distancia ${info.measurement_mm.toFixed(2)} mm · REFERENCE, no medición física`);return;}selection=info;renderPanel();}
function inspector(c){const wires=data.wiring.filter(w=>w.from_component===c.component_id||w.to_component===c.component_id);const gpio=data.pinout.filter(p=>p.device===c.component_id||p.device.includes('TOF')&&c.component_id.includes('TOF'));return `<span class="caption">${c.bom_id} / ${c.component_id}</span><h2>${esc(c.name)}</h2>${badge(c.measurement_status)}${badge(c.category,'')}<p>${esc(c.function)}</p><div class="actions"><button data-focus="${c.component_id}">Enfocar pieza</button><button data-related="${c.component_id}">Ver conexiones</button><button data-doc="${c.document_section}">Documentación</button></div>${['quantity','location','power','signal','controller','mechanical_parent','electrical_parent','fixation','calibration','faults','test','accessibility'].map(k=>field(({quantity:'Cantidad instancia',location:'Ubicación',power:'Alimentación',signal:'Señal',controller:'Controlador',mechanical_parent:'Soporte',electrical_parent:'Dominio',fixation:'Fijación',calibration:'Calibración',faults:'Fallo típico',test:'Prueba',accessibility:'Acceso'})[k],c[k])).join('')}<h3>GPIO asociados</h3>${gpio.map(p=>field(`GPIO${p.gpio} · pin ${p.physical_pin}`,p.signal)).join('')||'<p>Sin GPIO directo.</p>'}<h3>Conexiones trazables</h3>${wires.map(w=>`<button class="select-wide" data-wire="${w.id}">${w.id} · ${esc(w.signal)}</button>`).join('')||'<p>Interfaz mecánica o consumo de material.</p>'}`;}
function wireInspector(w){return `<span class="caption">${w.id} · ${w.harness_id}</span><h2>${esc(w.signal)}</h2>${badge(w.status,w.status==='BLOCKER'?'red':'yellow')}${Object.entries({FROM:`${w.from_component} ${w.from_pin}`,TO:`${w.to_component} ${w.to_pin}`,VOLTAGE:w.voltage,AWG:w.awg??'Cable original',COLOR:w.color,CONNECTOR:w.connector,FUSE:w.fuse,ROUTE:w.route,PROTECTION:w.protection,LENGTH:w.length_mm}).map(([k,v])=>field(k,v)).join('')}<p>Un trazado discontinuo representa una interfaz por resolver. No es una instrucción de unir 12 V a GPIO.</p><button data-focus="${w.to_component}">Ver destino</button>`;}
function operator(){const s=twin.fw.state,p=twin.plant;return `<div class="status-line">${badge('SIMULATION')}${badge(p.power?'ACTUADORES ON':'ACTUADORES OFF',p.power?'green':'')}</div><div class="big-state">${s==='READY'?'LISTO':s==='FAULT'?'FALLO':s==='REVIEW'?'REVISIÓN':s==='BOOT_SAFE'?'SIN ARMAR':'PROCESANDO'}</div><p>${esc(twin.fw.reason??(s==='BOOT_SAFE'?'Inicialización segura. Rearmar inicia homing con guía vacía.':'El Pico conceptual valida cada movimiento.'))}</p><div class="actions"><button data-action="rearm">Rearme físico simulado</button><button data-action="inspect_clear">Inspeccionar y retirar</button></div><h3>Objeto de demostración</h3><select id="object-kind" class="select-wide"><option value="0">PET</option><option value="1">PAPEL_CARTON</option><option value="2" selected>METAL_LATAS</option><option value="3">OTRO_SECO_CONOCIDO</option></select><button id="run-demo" class="select-wide" ${s==='READY'?'':'disabled'}>Depositar una pieza y cerrar tapa</button><p class="caption">La elección representa el objeto. El destino lo determina la política de percepción simulada.</p><div class="actions"><button data-toggle="lid">${p.lid?'Abrir':'Cerrar'} tapa</button><button data-toggle="door">${p.door?'Abrir':'Cerrar'} servicio</button><button id="release-estop">Liberar paro</button></div>${field('Estado',s)}${field('boot_id',twin.fw.boot)}${field('cycle_id',twin.fw.cycle)}${field('Pico USB',p.usb?'CONNECTED':'DISCONNECTED')}${field('Requested bin',twin.fw.operation?.dest)}${field('Confirmed index',p.confirmedIndex)}${field('Confirmed bin',twin.result?.confirmed_bin)}${field('Resultado',twin.result?.physical_result??'PENDING')}${field('Último material',twin.decision.predicted_class)}${field('Ciclo simulado',twin.result?`${twin.result.cycle_ms} ms`:'—')}<h3>Niveles orientativos</h3><div class="two-col">${p.tof.bins.map((b,i)=>`<div class="module">BIN${i} <small>${b.state}</small><br>${b.level===null?'UNKNOWN':b.level.toFixed(0)+'%'}<div class="level"><div style="width:${b.level??0}%"></div></div></div>`).join('')}</div>${field('Almacenamiento',p.flags.diskFull?'FULL':'SIMULATED AVAILABLE')}${field('Software','Digital Twin 1.0')}${field('Firmware','Modelo lógico JS 1.0')}${field('Hash modelo','No hay modelo entrenado: IA SIMULADA')}<div class="blocker"><strong class="warning">Diseño físico pendiente</strong><p>La cadena de corte, las interfaces eléctricas y las cotas requieren cierre antes de fabricar. Consulte la auditoría.</p></div>`;}
function renderPanel(){const panel=$('panel');$('panel-title').textContent=selection?.wireId?'INSPECTOR DE CONEXIÓN':selection?.componentId?'IDENTIDAD DEL COMPONENTE':mode;let html='';
 if(selection?.componentId){const c=data.components.find(c=>c.component_id===selection.componentId);html=c?inspector(c):'<p>Subconjunto de BOM-65.</p>';}
 else if(selection?.wireId)html=wireInspector(data.wiring.find(w=>w.id===selection.wireId));
 else if(mode==='BOM'){const bs=data.bom.filter(b=>(bomFilter==='ALL'||b.category===bomFilter)&&JSON.stringify(b).toLowerCase().includes(query.toLowerCase()));html=`<h2>82 entradas de compra</h2>${badge('82 / 82 documentadas','green')}<p>Cantidades originales conservadas. Las subdivisiones 3D pertenecen a la misma entrada de compra.</p><input id="bom-search" type="search" placeholder="Buscar componente o BOM" value="${esc(query)}"><select id="bom-filter" class="select-wide">${['ALL','MECHANICAL','ELECTRONICS','SENSOR','ACTUATOR','WIRING','FASTENER','MATERIAL','LOGISTICS'].map(c=>`<option ${bomFilter===c?'selected':''}>${c}</option>`).join('')}</select><table><thead><tr><th>ID</th><th>COMPONENTE / CANT.</th></tr></thead><tbody>${bs.map(b=>`<tr class="clickable" data-bom="${b.bom_id}"><td>${b.number.toString().padStart(2,'0')}</td><td>${esc(b.name)}<br><span class="caption">${esc(b.quantity)} · ${b.component_id}</span></td></tr>`).join('')}</tbody></table>`;}
 else if(mode==='MEDICIONES'){html=`<h2>Cotas de referencia</h2><p>Medir en el modelo produce una distancia geométrica. Introducir una medida física cambia a MEASURED; congelar es una acción separada.</p>${badge(`${Object.values(data.dimensions).filter(x=>x.status!=='FROZEN').length} sin congelar`)}<div class="actions"><button id="export-dimensions">Exportar dimensions.json</button><button id="measure-activate">Medir dos puntos 3D</button></div>${Object.entries(data.dimensions).map(([k,d])=>`<div class="measure-row"><strong>${k}</strong><span class="measurement-status">${d.status}</span><p>${esc(d.what)}<br>Instrumento: ${esc(d.tool)} · ${esc(d.tolerance)}<br>CAD: ${esc(d.cad_dependency)}</p><input type="number" step="any" value="${d.value}" id="dim-${k}" aria-label="${k}" ${d.status==='FROZEN'?'disabled':''}> ${d.unit}<button data-measured="${k}" ${d.status==='FROZEN'?'disabled':''}>Medido</button><button data-freeze="${k}" ${d.status==='MEASURED'?'':'disabled'}>Congelar</button>${d.status==='FROZEN'?`<button data-unfreeze="${k}">Descongelar</button>`:''}</div>`).join('')}`;}
 else if(mode==='FALLOS'){html=`<h2>30 escenarios causales</h2><p>Armar un fallo lo aplica al llegar a la fase indicada. Inicie después un ciclo. Se modifican la planta, los sensores o el enlace; los estados reaccionan a esas condiciones.</p><button id="fault-none" class="select-wide">Quitar fallo programado</button>${data.faults.map(f=>`<div class="fault-item"><button data-fault="${f.id}" ${twin.faults.selected?.id===f.id?'class="active"':''}>${f.id} · ${esc(f.title)}</button><p>${esc(f.phase)} → ${f.expected_state}<br>${esc(f.observation)}</p><details><summary>Recuperación</summary><p>${esc(f.recovery)}</p></details></div>`).join('')}`;}
 else if(mode==='ENSAMBLAJE'||mode==='BUILD SorTV1'){const s=data.assembly[assemblyStep-1];html=`<span class="caption">PASO ${String(s.step).padStart(2,'0')} / 22</span><h2>${s.title}</h2><progress value="${s.step}" max="22"></progress><div class="actions"><button id="assembly-prev" ${s.step===1?'disabled':''}>← Anterior</button><button id="assembly-next" ${s.step===22?'disabled':''}>Siguiente →</button></div>${[['ENTRADA',s.entry],['TRABAJO',s.work],['MEDICIÓN',s.measurement],['CRITERIO PASS',s.pass_criterion],['ERROR TÍPICO',s.typical_error],['NO CONTINUAR SI',s.stop_if],['HERRAMIENTAS',s.tools],['FIJACIÓN',s.fixation]].map(([k,v])=>`<h3>${k}</h3><p>${esc(v)}</p>`).join('')}<h3>Conjuntos de este paso</h3>${s.components.map(id=>`<button class="select-wide" data-component="${id}">${id}</button>`).join('')}`;scene.options.assemblyStep=s.step;for(const id of s.components)if(scene.model.nodes.has(id)){scene.selectComponent(id);break;}}
 else if(mode==='COMMISSIONING'){const c=data.commissioning[commissionStep];html=`${badge('CHECKLIST SIMULADO')}<h2>${c.id} · ${c.title}</h2><p>${esc(c.stop_if)}</p>${c.checks.map((x,i)=>`<label class="check"><input type="checkbox" data-commission-check="${i}" ${progress[c.id]?.checks?.[x]?'checked':''}>${esc(x)}</label>`).join('')}<div class="actions"><button id="commission-prev" ${commissionStep===0?'disabled':''}>← Anterior</button><button id="commission-next">${commissionStep===10?'Cerrar checklist':'Completar y continuar'}</button></div>${data.commissioning.map(d=>field(d.id,progress[d.id]?.completed?'SIMULATED CHECKED':'PENDING')).join('')}<p>PHYSICAL RESULT permanece vacío. Marcar una casilla no acredita una prueba sobre el equipo.</p><button id="export-commission">Exportar checklist</button>`;}
 else if(mode==='TEST CENTER'){html=`<h2>Pruebas P01–P16</h2><p>Ejecute el contrato lógico. Los ensayos térmicos, de visión y mecánicos requieren datos del prototipo.</p><button id="tests-all" class="select-wide">Ejecutar las 16 pruebas simulables</button>${data.acceptance.map(p=>`<div class="fault-item"><strong>${p.id} ${p.name}</strong><p>${esc(p.expected)}</p><button data-test="${p.id}">Ejecutar ${p.id}</button> ${badge(testResults[p.id]?.simulated_result??'PENDING',testResults[p.id]?.simulated_result==='SIMULATED PASS'?'green':'yellow')}<div class="caption">PHYSICAL RESULT: vacío</div>${testResults[p.id]?`<details><summary>Evidencia</summary><pre>${esc(JSON.stringify(testResults[p.id].evidence,null,2))}</pre></details>`:''}</div>`).join('')}<button id="export-tests">Exportar pruebas</button>`;}
 else if(mode==='ESTADOS'){html=`<h2>Autoridad física Pico</h2><p>El modelo no emula un RP2040. Reproduce guardas, temporizadores y respuestas físicas conceptuales.</p><div class="state-list">${data.states.map(s=>`<div class="state-node ${s.name===twin.fw.state?'current':''}" data-state="${s.name}">${s.name}</div>`).join('')}</div><h3>Guardas actuales</h3>${field('Resguardos',twin.plant.lid&&twin.plant.door)}${field('Potencia',twin.plant.power)}${field('CLOSED',twin.plant.gateClosed)}${field('Guía vacía inferida',twin.plant.routeClear)}${field('Índice confirmado',twin.plant.confirmedIndex)}${field('Heartbeat age',twin.clock.now-twin.fw.lastHeartbeat+' ms')}${field('Estado restante',data.states.find(s=>s.name===twin.fw.state)?.timeout_ms??'sin timeout de reposo')}<h3>Transiciones</h3>${data.states.map(s=>`<details><summary>${s.name}</summary><p>Evento: ${s.event}<br>Guarda: ${s.guard}<br>Acción: ${s.action}<br>Timeout: ${s.timeout_ms??'—'} ms<br>Salida: ${s.next}</p></details>`).join('')}`;}
 else if(mode==='SOFTWARE'){html=`<h2>Pi · Percepción y decisión</h2>${data.software.map(s=>`<div class="module ${twin.pi.modules[s.name]==='ACTIVE'?'active':''}"><small>${twin.pi.modules[s.name]}</small><button data-module="${s.id}" class="quiet">${s.name}</button></div>${activeModule===s.id?['input','process','output','failures','dependencies'].map(k=>field(k.toUpperCase(),s[k])).join(''):''}`).join('')}<h3>Pipeline de IA</h3><p>ROI → RGB → 224×224 FP32 → ImageNet → MobileNetV3 Small → probabilidades → consenso.</p>${twin.pi.frames.length?`<table><tr><th>CLASE</th><th>PROB. SIMULADA</th></tr>${['PET','PAPEL_CARTON','METAL_LATAS','OTRO_SECO_CONOCIDO'].map((x,i)=>`<tr><td>${x}</td><td>${twin.pi.frames.at(-1).probabilities[i].toFixed(2)}</td></tr>`).join('')}</table>`:'<p>Tres frames nuevos al iniciar INSPECT.</p>'}<p>top1 &gt; 0.80 · margen &gt; 0.15 · acuerdo ≥2/3. El simulador no incluye pesos entrenados ni ejecuta inferencia ONNX.</p>${field('Decisión',twin.decision.decision)}${field('Material',twin.decision.predicted_class)}`;}
 else if(mode==='CABLEADO'||mode==='SEÑALES'||mode==='ELECTRÓNICA'){html=`<h2>${mode==='ELECTRÓNICA'?'Panel y dominios':'Arnés trazable'}</h2><p>Elija una ruta o una conexión. Ámbar discontinuo: interfaz aún no resuelta.</p><div class="actions"><button data-trace="CMP-06|ELEC-12">Pico → DRV</button><button data-trace="ELEC-31|ACT-09">12 V → NEMA</button><button data-trace="ELEC-31|ACT-15">12 V → Servo</button></div>${field('Lógica','5.1 V → Pi → USB → Pico')}${field('Actuadores',twin.plant.power?'12 V autorizado':'12 V cortado')}${field('Servo',`${twin.plant.servoSupply} V SIMULATED`)}<p>Los positivos no se unen. El retorno de motor/servo vuelve a la fuente; una unión de referencia conecta GND Pico.</p><table><tr><th>ID</th><th>FROM → TO</th></tr>${data.wiring.map(w=>`<tr class="clickable" data-wire="${w.id}"><td>${w.id}</td><td>${esc(w.from_component)} → ${esc(w.to_component)}<br><span class="caption">${esc(w.signal)} · ${esc(w.voltage)}</span></td></tr>`).join('')}</table>`;}
 else if(mode==='MANTENIMIENTO'){const ids=['CMP-01','CMP-06','CMP-05','ELEC-12','SAFE-35','ELEC-32','ELEC-HX711','ACT-15','ACT-09','SENS-TOF0','MECH-66','CMP-02','BIN-00'];html=`<h2>Acceso y mantenimiento</h2><p>Aislar potencia antes de retirar paneles. Los bins traseros pueden requerir extraer los delanteros; confirmar con medidas reales.</p><h3>Antes de cada sesión</h3><p>Cuatro bins presentes; guía vacía; bandeja limpia; cámara firme; luz uniforme; tara; espacio de disco; E-STOP; rearme; un ciclo por bin.</p><h3>Acceder a un componente</h3>${ids.map(id=>`<button class="select-wide" data-maintain="${id}">${id} · ${data.components.find(c=>c.component_id===id)?.name??''}</button>`).join('')}<h3>Después</h3><p>Actuadores OFF, apagado correcto, limpieza en seco, revisión de tornillería, copia de registros e incidentes.</p>`;}
 else if(mode==='EVIDENCIA'){html=`<h2>Registro de simulación</h2><p>Todos los archivos exportados incluyen source: SIMULATION. La columna physical_result describe el desenlace virtual; no cambia el origen de la evidencia.</p><div class="actions">${['json','jsonl','csv'].map(f=>`<button data-export="${f}">Exportar ${f.toUpperCase()}</button>`).join('')}</div>${field('Eventos',twin.logger.events.length)}${field('Contadores',twin.logger.counts.join(' / '))}${field('Journal pendiente',twin.logger.journal.pending)}<h3>Último ciclo</h3><pre>${esc(JSON.stringify(twin.result,null,2))}</pre><h3>Frames 00–38</h3>${data.storyboard.map(f=>`<div class="caption">${String(f.frame).padStart(2,'0')} · ${esc(f.title)}</div>`).join('')}`;}
 else if(mode==='RIESGOS'){html=`<h2>Auditoría de interferencias</h2>${interferenceAudit(data.dimensions).map(r=>`<div class="blocker">${badge(r.status,r.status==='BLOCKER'?'red':'yellow')}<strong>${r.title}</strong><p>${esc(r.scope)}${r.margin_mm!==undefined?`<br>Margen de envolvente: ${r.margin_mm} mm REFERENCE`:''}</p></div>`).join('')}<h3>Bloqueos y propuestas</h3>${data.risks.map(r=>`<details><summary>${r.id} · ${r.status}</summary><p>${r.finding}</p><p>Medir: ${r.measure}</p><p>Propuesta no aprobada: ${r.proposal}</p></details>`).join('')}<p>ADDED 0 · REMOVED 0 · CHANGED 0. Esto conserva la BOM; no significa que el hardware esté listo para fabricar.</p>`;}
 else if(mode==='EXPLODED'){html=`<h2>Grupos de montaje A–O</h2><p>Use el deslizador para separar conjuntos. Las fichas conservan IDs y referencias durante la explosión.</p>${data.groups.map(g=>`<div class="module"><strong>${g.id} · ${g.title}</strong><p>BOM ${g.bom_numbers.map(n=>String(n).padStart(2,'0')).join(', ')}<br>Etapa ${g.assembly_step}</p><button data-build="${g.assembly_step}">Ver montaje</button></div>`).join('')}`;}
 else html=operator();panel.innerHTML=html;bindPanel();}
function bindPanel(){const panel=$('panel');panel.onclick=async e=>{const b=e.target.closest('button,tr[data-bom],tr[data-wire]');if(!b)return;try{if(b.dataset.action){const ok=twin.action(b.dataset.action);toast(ok?'Estímulo físico simulado aplicado':'Guardas no permiten esta acción');if(ok&&b.dataset.action==='rearm')twin.clock.paused=false;renderPanel();}if(b.id==='run-demo'){const k=Number($('object-kind').value);if(twin.startDemo(k)){twin.clock.paused=false;scene.options.opacity=.08;scene.options.path=true;syncControls();renderPanel();}else toast('Primero complete rearme y homing.');}if(b.dataset.toggle){twin.action(b.dataset.toggle,!twin.plant[b.dataset.toggle]);renderPanel();}if(b.id==='release-estop'){twin.action('estop',false);renderPanel();toast('Paro liberado; se conserva el enclavamiento.');}if(b.dataset.bom){const c=data.components.find(c=>c.bom_id===b.dataset.bom&&c.modeled)??data.components.find(c=>c.bom_id===b.dataset.bom);selection={componentId:c.component_id};scene.selectComponent(c.component_id);renderPanel();}if(b.dataset.component){selection={componentId:b.dataset.component};scene.selectComponent(b.dataset.component);renderPanel();}if(b.dataset.focus)scene.selectComponent(b.dataset.focus,true);if(b.dataset.related){scene.options.wires='ALL';scene.options.opacity=.08;scene.selectComponent(b.dataset.related);syncControls();}if(b.dataset.doc){const text=await fetch('./docs/architecture.md').then(r=>r.text());download('SorTV1_architecture.md',text,'text/markdown');}if(b.dataset.wire){selection={wireId:b.dataset.wire};scene.selectWire(b.dataset.wire);renderPanel();syncControls();}if(b.dataset.trace){const [a,z]=b.dataset.trace.split('|');const path=traceWires(data.wiring,a,z);scene.options.wires='ALL';toast(`Ruta: ${path.join(' → ')||'Interfaz directa no resuelta'}`);if(path.length){scene.selectWire(path[0]);selection={wireId:path[0]};renderPanel();}}if(b.dataset.fault){twin.faults.arm(b.dataset.fault);toast(`${b.dataset.fault} preparado; se aplicará en ${twin.faults.selected.phase}`);renderPanel();}if(b.id==='fault-none'){twin.faults.arm(null);renderPanel();}if(b.id==='assembly-prev'||b.id==='assembly-next'){assemblyStep+=b.id==='assembly-prev'?-1:1;renderPanel();}if(b.dataset.build){assemblyStep=Number(b.dataset.build);setMode('ENSAMBLAJE');}if(b.dataset.measured){const k=b.dataset.measured;measureDimension(data.dimensions,k,Number($(`dim-${k}`).value));saveDims();}if(b.dataset.freeze){freezeDimension(data.dimensions,b.dataset.freeze);saveDims();}if(b.dataset.unfreeze){data.dimensions[b.dataset.unfreeze].status='MEASURED';saveDims();}if(b.id==='export-dimensions')download('dimensions.json',JSON.stringify({source:'SIMULATION',dimensions:data.dimensions},null,2));if(b.id==='measure-activate'){scene.measureMode=!scene.measureMode;toast('Seleccione dos superficies del modelo.');}if(b.id==='commission-prev'){commissionStep--;renderPanel();}if(b.id==='commission-next'){completeCommissionStep(progress,data.commissioning,commissionStep);localStorage.setItem('sortv1_commissioning_simulation',JSON.stringify(progress));if(commissionStep<10)commissionStep++;else toast('Checklist simulado completo; resultado físico sigue vacío.');renderPanel();}if(b.id==='export-commission')download('commissioning_simulation.json',JSON.stringify({source:'SIMULATION',progress,physical_result:null},null,2));if(b.dataset.test){b.disabled=true;testResults[b.dataset.test]=runAcceptance(data,b.dataset.test);renderPanel();}if(b.id==='tests-all'){b.disabled=true;for(const p of data.acceptance){testResults[p.id]=runAcceptance(data,p.id);await new Promise(r=>setTimeout(r,0));}renderPanel();}if(b.id==='export-tests')download('acceptance_simulation.json',JSON.stringify({source:'SIMULATION',results:testResults},null,2));if(b.dataset.module){activeModule=activeModule===b.dataset.module?null:b.dataset.module;renderPanel();}if(b.dataset.maintain){scene.options.serviceOpen=true;scene.options.opacity=.05;scene.selectComponent(b.dataset.maintain,true);selection={componentId:b.dataset.maintain};renderPanel();}if(b.dataset.export)download(`SorTV1_SIMULATION.${b.dataset.export}`,twin.logger.export(b.dataset.export),b.dataset.export==='csv'?'text/csv':'application/json');}catch(e){toast(e.message);}};
 if($('bom-search'))$('bom-search').oninput=e=>{query=e.target.value;const pos=e.target.selectionStart;renderPanel();$('bom-search').focus();$('bom-search').setSelectionRange(pos,pos);};if($('bom-filter'))$('bom-filter').onchange=e=>{bomFilter=e.target.value;renderPanel();};panel.onchange=e=>{if(e.target.dataset.commissionCheck!==undefined){const c=data.commissioning[commissionStep];progress[c.id]??={checks:{},completed:false,source:'SIMULATION',physical_result:null};progress[c.id].checks[c.checks[Number(e.target.dataset.commissionCheck)]]=e.target.checked;progress[c.id].completed=false;localStorage.setItem('sortv1_commissioning_simulation',JSON.stringify(progress));}};
}
function saveDims(){localStorage.setItem('sortv1_dimensions_user',JSON.stringify(data.dimensions));scene.rebuild();renderPanel();toast('Dimensión guardada localmente; exporte el archivo para compartirla.');}
const monitorModes=['SENSORES','GPIO','PROTOCOLO','EVENTOS','CAUSA','ACTUADORES','ESTADOS'];function renderMonitor(){ $('monitor-tabs').innerHTML=monitorModes.map(m=>`<button data-monitor="${m}" class="${monitor===m?'active':''}">${m}</button>`).join('');const p=twin.plant;let h='';if(monitor==='SENSORES')h=`<div class="sensor-grid">${Object.entries(p.sensors()).filter(([k])=>!['TOF','source'].includes(k)).map(([k,v])=>`<div>${k} <strong>${esc(Array.isArray(v)?v.join(' / '):v)}</strong></div>`).join('')}${p.tof.bins.map((b,i)=>`<div>TOF${i} <strong>${b.distance??'UNKNOWN'} mm · ${b.state}</strong></div>`).join('')}</div>`;if(monitor==='GPIO')h=`<div class="sensor-grid">${twin.gpio().map(p=>`<div>GP${p.gpio} ${p.signal} <strong>${p.live}</strong></div>`).join('')}</div>`;if(monitor==='PROTOCOLO')h=`<button id="protocol-raw">${rawProtocol?'RAW':'DECODED'}</button>`+twin.logger.protocol.slice(-22).reverse().map(r=>`<div class="log-row"><span>+${r.t_ms}ms</span><span class="kind">${r.direction} →</span><span>${esc(rawProtocol?r.raw:JSON.stringify(r.message))} <span class="muted">age=${twin.clock.now-r.t_ms} ms</span></span></div>`).join('');if(monitor==='EVENTOS')h=twin.logger.events.slice(-35).reverse().map((r,i)=>`<div class="log-row clickable" data-event="${twin.logger.events.length-1-i}"><span>+${r.t_ms}</span><span class="kind">${r.type}</span><span>${esc(r.detail)}</span></div>`).join('');if(monitor==='CAUSA')h=twin.cause?`<div class="sensor-grid">${Object.entries(twin.cause).filter(([k])=>k!=='confirmation').map(([k,v])=>`<div>${k.toUpperCase()}<br><strong>${esc(v)}</strong></div>`).join('')}</div><p>Confirmación: ${esc(JSON.stringify(twin.cause.confirmation))}</p>`:'Esperando evento';if(monitor==='ACTUADORES')h=`<div class="sensor-grid"><div>NEMA <strong>${p.rotorCommand?'MOVING':'STOPPED'}</strong></div><div>nEN <strong>${p.nEN}</strong></div><div>DIR <strong>${p.dir}</strong></div><div>STEP RATE <strong>${p.stepRate.toFixed(1)} Hz</strong></div><div>ANGLE <strong>${p.rotorAngle.toFixed(1)}° SIM</strong></div><div>TARGET <strong>${twin.fw.operation?.dest??'ROT0'}</strong></div><div>CONFIRMED <strong>${p.confirmedIndex??'NONE'}</strong></div><div>SERVO <strong>${p.gateCommand===null?'DISABLED':'PWM'}</strong></div><div>GATE ANGLE <strong>${p.gateAngle.toFixed(1)}° SIM</strong></div><div>OPEN / CLOSED <strong>${p.gateOpen} / ${p.gateClosed}</strong></div></div>`;if(monitor==='ESTADOS')h=`<div class="sensor-grid">${data.states.map(s=>`<div class="state-node ${twin.fw.state===s.name?'current':''}">${s.name}</div>`).join('')}</div>`;$('monitor-content').innerHTML=h;}
$('monitor-tabs').onclick=e=>{const b=e.target.closest('[data-monitor]');if(b){monitor=b.dataset.monitor;renderMonitor();}};$('monitor-content').onclick=e=>{if(e.target.id==='protocol-raw'){rawProtocol=!rawProtocol;renderMonitor();}const r=e.target.closest('[data-event]');if(r){twin.clock.paused=true;const row=twin.logger.events[Number(r.dataset.event)];selection=null;$('panel-title').textContent='SNAPSHOT DEL EVENTO';$('panel').innerHTML=`<h2>${row.type}</h2><pre>${esc(JSON.stringify(row,null,2))}</pre><p>Instantánea registrada. La vista 3D conserva la posición actual del simulador.</p>`;}};
$('play').onclick=()=>{twin.clock.paused=!twin.clock.paused;};$('step').onclick=()=>{twin.clock.paused=true;twin.stepEvent();renderPanel();renderMonitor();};$('speed').onchange=e=>twin.clock.speed=Number(e.target.value);$('estop').onclick=()=>{twin.action('estop',true);twin.tick();renderPanel();};$('transparent').onclick=()=>{scene.options.opacity=scene.options.opacity>.3?.08:1;syncControls();};$('reset-view').onclick=()=>scene.resetCamera();$('path').onclick=()=>scene.options.path=!scene.options.path;$('measure').onclick=()=>{scene.measureMode=!scene.measureMode;$('measure').classList.toggle('active',scene.measureMode);toast(scene.measureMode?'Seleccione dos puntos de la geometría.':'Medición desactivada');};$('opacity').oninput=e=>scene.options.opacity=Number(e.target.value);$('explode').oninput=e=>scene.options.explode=Number(e.target.value);$('wire-filter').onchange=e=>{scene.options.wires=e.target.value;if(e.target.value!=='NONE')scene.options.opacity=.1;};$('open-info').onclick=()=>setMode('RIESGOS');$('expand-panel').onclick=()=>document.body.classList.toggle('panel-expand');
let last=performance.now(),uiLast=0,prevState=twin.fw.state,prevPower=false;function loop(now){const dt=Math.min(now-last,100);last=now;if(!twin.clock.paused){twin.clock.accumulator+=dt*twin.clock.speed;while(twin.clock.accumulator>=20){twin.tick(20);twin.clock.accumulator-=20;}}scene.render(twin);if(now-uiLast>180){uiLast=now;$('time').textContent=`T+${String(twin.clock.now).padStart(5,'0')} ms`;$('phase').textContent=twin.fw.state;$('status-pill').textContent=twin.fw.state;$('status-pill').style.color=twin.fw.state==='FAULT'?'#ef827c':twin.fw.state==='READY'?'#79c9a1':'#e7b86b';$('play').textContent=twin.clock.paused?'▶ Play':'Ⅱ Pause';renderMonitor();if(mode==='SOFTWARE'&&!selection&&twin.fw.state==='WAIT_DECISION')renderPanel();if(prevState!==twin.fw.state||prevPower!==twin.plant.power){prevState=twin.fw.state;prevPower=twin.plant.power;if(!selection&&['PRODUCTO','INTERIOR','SIMULACIÓN','ESTADOS','SOFTWARE'].includes(mode))renderPanel();}}requestAnimationFrame(loop);}renderPanel();renderMonitor();requestAnimationFrame(loop);
